argv:
$ErrorActionPreference='Stop'
Add-Type -AssemblyName UIAutomationClient
Add-Type -AssemblyName UIAutomationTypes
Add-Type @"
using System;
using System.Runtime.InteropServices;
public static class W32Publish {
 [DllImport("user32.dll")] public static extern bool SetForegroundWindow(IntPtr hWnd);
}
"@
$edge=Get-Process msedge -ErrorAction SilentlyContinue | Where-Object {$_.MainWindowHandle -ne 0} | Select-Object -First 1
if($null -eq $edge){throw 'Edge not visible'}
[W32Publish]::SetForegroundWindow($edge.MainWindowHandle)|Out-Null
$root=[System.Windows.Automation.AutomationElement]::FromHandle($edge.MainWindowHandle)
$all=$root.FindAll([System.Windows.Automation.TreeScope]::Descendants,[System.Windows.Automation.Condition]::TrueCondition)
$publish=$null
for($i=0;$i -lt $all.Count;$i++){
  $e=$all.Item($i)
  if($e.Current.ControlType -eq [System.Windows.Automation.ControlType]::Button -and [string]$e.Current.Name -eq '發佈' -and $e.Current.IsEnabled){
    $r=$e.Current.BoundingRectangle
    if(-not [double]::IsInfinity($r.Y) -and $r.Y -gt 500){$publish=$e;break}
  }
}
if($null -eq $publish){throw 'Threads publish button not found'}
$inv=$publish.GetCurrentPattern([System.Windows.Automation.InvokePattern]::Pattern)
$inv.Invoke()
Start-Sleep -Seconds 10

$root=[System.Windows.Automation.AutomationElement]::FromHandle($edge.MainWindowHandle)
$all=$root.FindAll([System.Windows.Automation.TreeScope]::Descendants,[System.Windows.Automation.Condition]::TrueCondition)
$hits=@()
$toasts=@()
for($i=0;$i -lt $all.Count;$i++){
  $e=$all.Item($i)
  $name=[string]$e.Current.Name
  if($name){
    if($name -like '*剛剛真的看著 ChatGPT*' -or $name -like '*你最想把哪件事丟給兩個 AI*'){
      $r=$e.Current.BoundingRectangle
      $hits += [pscustomobject]@{type=$e.Current.ControlType.ProgrammaticName;name=$name;x=[string]$r.X;y=[string]$r.Y;w=[string]$r.Width;h=[string]$r.Height}
    }
    if($name -match '已發佈|已發布|發佈成功|已分享|發文成功'){
      $toasts += $name
    }
  }
}
[pscustomobject]@{
  publish_invoked=$true
  title=$edge.MainWindowTitle
  post_hits=$hits
  toast_hits=$toasts
}|ConvertTo-Json -Depth 6 -Compress
